local KTool = CS.Engine.Lib.KTool

---@class MaidCoffeeGuestController
---@field New fun():MaidCoffeeGuestController
local MaidCoffeeGuestController = Class('MaidCoffeeGuestController')
local MaidCoffeeUtils = import("Game.MaidCoffee.MaidCoffeeUtils")
local cs_coroutine     = require "XLua.cs_coroutine"
local MaidCoffeeConstants = import("Game.MaidCoffee.MaidCoffeeConstants")
local Quaternion = CS.UnityEngine.Quaternion
local Vector3           = Vector3
local ResourceModule = CS.Engine.Modules.ResourceModule

function MaidCoffeeGuestController:__init()
    self.eventData = nil
    self.eventVo = nil
    self.collectVo = nil
    self.rootGo = nil
    self.uiParent = nil
    self.camera = nil
    self.isFinishEvent = false
    self._isInitComplete = false
    self.posIndex = nil
end

function MaidCoffeeGuestController:__delete()
    self.eventData = nil
    self.eventVo = nil
    self.collectVo = nil
    self.rootGo = nil
    self.uiParent = nil
    self.camera = nil
    self.isFinishEvent = nil
    self._isInitComplete = nil
    self.posIndex = nil
    if not isNull(self._co) then
        cs_coroutine.stop(self._co)
        self._co = nil
    end

    if not isNull(self.guestGo) then
        KTool.SafeDelete(self.guestGo,true)
        self.guestGo = nil
    end

    if not isNull(self._bubbleGo) then
        KTool.SafeDelete(self._bubbleGo,true)
        self._bubbleGo = nil
    end
end

--- Init
---@param data table 事件数据
---@param rootGo UnityEngine.Transform 客人挂载点
---@param playNode UnityEngine.Transform 主角
---@param uiParent UnityEngine.GameObject 头顶UI父节点
---@param camera UnityEngine.Camera 跟随主角的相机
function MaidCoffeeGuestController:Init(data,rootGo,playNode,uiParent,camera,posIndex)
    self.eventData = data
    self.eventVo = MaidCoffeeUtils.GetGuestEventVo(self.eventData.eventId)
    self.collectVo = MaidCoffeeUtils.GetGuestCollectionVo(self.eventData.visitorId)
    if isNull(self.collectVo) then
        printError("客人图鉴信息为空 ----->>>>>id = %s ",self.eventData.visitorId)
        return
    end
    self.rootGo = rootGo
    self.playNode = playNode
    self.uiParent = uiParent
    self.camera = camera
    self.isFinishEvent = false
    self.posIndex = posIndex
    self:AddGuest(self.collectVo.resource,self.rootGo)
    self._isInitComplete = true
end

function MaidCoffeeGuestController:Update()

end

function MaidCoffeeGuestController:SetFinishEvent(status)
    self.isFinishEvent = status
end

function MaidCoffeeGuestController:SetGuestStatus(status)
    if not isNull(self.rootGo) then
        KTool.SetActive(self.rootGo.gameObject,status)
    end
end

function MaidCoffeeGuestController:GetGuestPosIndex()
    return self.posIndex
end

function MaidCoffeeGuestController:GetGuestGo()
    return self.guestGo
end

function MaidCoffeeGuestController:AddGuest(prefabPath,parent)
    if string.isEmpty(prefabPath) then
        return nil
    end
    ResourceModule.LoadBundleAsync(prefabPath, function(_loader, isOk, resultObject)
        if isOk then
            if not isNull(parent) then
                local guestGo = _loader:Instantiate()
                if not isNull(guestGo) then
                    xTry(function()
                        KTool.SetParent(guestGo,parent.gameObject,false)
                        self.guestGo = guestGo
                        ---等客人出来以后再来刷新头显  防止头显先刷出来 找不到客人
                        local isOther = self:IsOther()
                        if not isOther then
                            self:CreateBubbleNode(self.uiParent,self.eventVo.npcId)
                        end
                    end)
                end
            end
        end
    end)
end

function MaidCoffeeGuestController:CreateBubbleNode(parent, npcId)
    if isNull(parent) then return end
    self._co = cs_coroutine.start(function ()
        local bubbleName = "Bubble" .. npcId
        local go = parent.transform:Find(bubbleName)
        if not isNull(go) then
            self:OnEventCreateBubbleSuccess(npcId,go)
            return
        end
        local MaidCoffeeConstants = MaidCoffeeConstants
        go = GameUtils.LoadBundleAsync(MaidCoffeeConstants.PrefabPath.BubblePath, parent, false)
        if not isNull(parent) and not isNull(go) then
            go.name = bubbleName
            KTool.SetLayer(parent.gameObject, go, true)
            self:OnEventCreateBubbleSuccess(npcId,go)
        end
    end)
end

function MaidCoffeeGuestController:OnEventCreateBubbleSuccess(npcId, go)
    if self.eventVo.npcId ~= npcId then
        return
    end
    self._bubbleGo = go
    self:FreshBubbleNodePosition()
    ---@type MapDecryptionRoleDialogueBubble
    local env = CfUtils.GetLuaScr(go, MaidCoffeeConstants.EnvPath.BubbleNode)
    if not isNull(env) then
        env:InitUI(self.collectVo,self.eventData.eventId)
    end
end

function MaidCoffeeGuestController:ExitScene()
    self:Delete()
end

function MaidCoffeeGuestController:FreshBubbleNodePosition()
    if not self._isInitComplete then return end
    if isNull(self._bubbleGo) then return end
    local bubbleTrans = self._bubbleGo.transform
    local position = self.rootGo.transform.position
    position.y = position.y + 1.8
    local isChange = Vector3.Distance(bubbleTrans.position, position) > 0.001
    if isChange then
        bubbleTrans.position = position
        local fwd = self.guestGo.transform.forward
        bubbleTrans.localRotation = Quaternion.LookRotation(fwd)
    end
    -- 让 ui元素始终朝向 mainCamera
    local mainCamera = CS.Game.Native.URP.URPCameraController.Instance.mainCamera
    local lookAtPos = bubbleTrans.position + mainCamera.transform.rotation * Vector3.unity_vector3.back
    local worldUpDir = mainCamera.transform.rotation * Vector3.unity_vector3.up
    bubbleTrans:LookAt( lookAtPos, worldUpDir )
    bubbleTrans:Rotate( 0.0, 180.0, 0.0 )
    return isChange
end

function MaidCoffeeGuestController:IsNearGuest()
    if not self._isInitComplete then return end
    if isNull(self.playNode) then return end
    if isNull(self.rootGo) then return end
    local isOther = self:IsOther()
    if isOther then
        return false
    end
    local dis = Vector3.Distance(self.rootGo.position, self.playNode.position)
    local roleAngle = MaidCoffeeUtils.CalcAngleAndClockwise(self.playNode.forward, self.rootGo.position, self.playNode.position)

    if dis <= MaidCoffeeConstants.NearDistance and roleAngle < 90 and not self.isFinishEvent then
        return true
    end
    return false
end

function MaidCoffeeGuestController:IsOther()
    local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local maidCoffeeHomeDojo = maidCoffeeComponent:GetMaidCoffeeHomeDoJo()
    local isOther = maidCoffeeHomeDojo:IsOther()
    return isOther
end

return MaidCoffeeGuestController